/** The public calendar feed Worker's config (generated by `host-configs.ts`). */
import { siteBindingName } from '@hearthlog/contracts/calendar/feed-contract';
import type { InfrastructureDefinition } from '../tenants/tenant-config.js';
import { WRANGLER_BASE } from '../tenants/wrangler-base.js';

/** Rate-limit namespace ids only have to be unique in the account. */
const LIMITER = { name: 'FEEDS_LIMITER', namespace_id: '21002', simple: { limit: 60, period: 60 } };

/**
 * The feed Worker: the feed bucket and one renderer service binding per site it serves (the sites of the shared stack,
 * or the one site of an own stack). It holds nothing else of a site and has no Ledger credential.
 */
export function buildCalendarPublicConfig(infrastructure: InfrastructureDefinition, siteIds: readonly string[]) {
    return {
        name: infrastructure.calendarPublicWorker,
        main: './index.ts',
        compatibility_date: WRANGLER_BASE.compatibility_date,
        workers_dev: true,
        preview_urls: false,
        // The feed URL carries the secret, and invocation logs record request paths.
        observability: { enabled: false },
        vars: { PUBLIC_ORIGIN: infrastructure.calendarPublicOrigin },
        r2_buckets: [{ binding: 'CALENDAR_FEEDS', bucket_name: infrastructure.calendarFeedsBucket }],
        services: siteIds.map((id) => ({ binding: siteBindingName(id), service: id, entrypoint: 'CalendarFeedRenderer' })),
        ratelimits: [LIMITER],
    };
}
